package ops

import (
	"strings"
	"time"

	"github.com/oklog/ulid/v2"
)

// OpType represents the type of operation performed on a dossier entry.
type OpType string

const (
	OpAdd       OpType = "add"
	OpAmend     OpType = "amend"
	OpSupersede OpType = "supersede"
	OpRetire    OpType = "retire"
	OpMove      OpType = "move"
	OpSplit     OpType = "split"
)

// Provenance constants representing the source of an operation.
const (
	SourceTurnNote      = "turn-note"
	SourceSidecar       = "sidecar"
	SourceSeed          = "seed"
	SourcePA            = "pa"
	SourceHuman         = "human"
	SourceConsolidation = "consolidation"
)

// Op represents a single operation targeting a specific dossier entry.
type Op struct {
	Type         OpType         `json:"type"`
	EntryID      string         `json:"entry_id"`
	DossierScope string         `json:"dossier_scope,omitempty"`
	Timestamp    time.Time      `json:"timestamp"`
	Source       string         `json:"source"`
	SessionID    string         `json:"session_id,omitempty"`
	Fields       map[string]any `json:"fields"`
}

// OpBatch represents a batch of ops written to an append-only JSON file.
type OpBatch struct {
	Version   int       `json:"version"`
	Ops       []Op      `json:"ops"`
	CreatedAt time.Time `json:"created_at"`
	BatchID   string    `json:"batch_id"`
}

// NewBatchID generates a new standard ULID string for a batch.
func NewBatchID() string {
	return ulid.Make().String()
}

// NewBatchIDWithTime generates a new standard ULID string for a batch using the specified time.
func NewBatchIDWithTime(t time.Time) string {
	return ulid.MustNew(ulid.Timestamp(t), ulid.DefaultEntropy()).String()
}

// NewEntryID generates a new entry ID consisting of prefix + ULID.
func NewEntryID(prefix string) string {
	return NewEntryIDWithTime(prefix, time.Now())
}

// NewEntryIDWithTime generates a new entry ID with prefix + ULID using the specified time.
func NewEntryIDWithTime(prefix string, t time.Time) string {
	id := ulid.MustNew(ulid.Timestamp(t), ulid.DefaultEntropy()).String()
	prefix = strings.TrimSpace(prefix)
	if prefix == "" {
		return id
	}
	prefix = strings.TrimSuffix(prefix, "-")
	return prefix + "-" + id
}

// NewBatch creates a new OpBatch with schema version 1 and current UTC timestamp.
func NewBatch(ops []Op) OpBatch {
	return NewBatchWithTime(ops, time.Now().UTC())
}

// NewBatchWithTime creates a new OpBatch with schema version 1 and the specified timestamp.
func NewBatchWithTime(batchOps []Op, t time.Time) OpBatch {
	if batchOps == nil {
		batchOps = []Op{}
	}
	return OpBatch{
		Version:   1,
		Ops:       batchOps,
		CreatedAt: t.UTC(),
		BatchID:   NewBatchIDWithTime(t),
	}
}

package ops

import (
	"errors"
	"fmt"
	"strings"
)

// ValidateOp validates a single op against the v2 op specification rules.
func ValidateOp(op Op) error {
	switch op.Type {
	case OpAdd:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("add: entry_id is required")
		}
		if strings.TrimSpace(op.DossierScope) == "" {
			return errors.New("add: dossier_scope is required")
		}
		if op.Fields == nil {
			return errors.New("add: fields is required")
		}
		v, ok := op.Fields["text"]
		if !ok || v == nil {
			return errors.New("add: fields must include text")
		}
		textStr, ok := v.(string)
		if !ok || strings.TrimSpace(textStr) == "" {
			return errors.New("add: fields text must be a non-empty string")
		}

	case OpAmend:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("amend: entry_id is required")
		}
		if op.Fields == nil || len(op.Fields) == 0 {
			return errors.New("amend: fields is required")
		}
		// DossierScope is optional (unchanged if empty)

	case OpSupersede:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("supersede: entry_id is required")
		}
		if op.Fields == nil {
			return errors.New("supersede: fields is required")
		}
		newIDVal, ok := op.Fields["new_entry_id"]
		if !ok || newIDVal == nil {
			return errors.New("supersede: fields must include new_entry_id")
		}
		newIDStr, ok := newIDVal.(string)
		if !ok || strings.TrimSpace(newIDStr) == "" {
			return errors.New("supersede: fields new_entry_id must be a non-empty string")
		}
		textVal, ok := op.Fields["text"]
		if !ok || textVal == nil {
			return errors.New("supersede: fields must include text")
		}
		textStr, ok := textVal.(string)
		if !ok || strings.TrimSpace(textStr) == "" {
			return errors.New("supersede: fields text must be a non-empty string")
		}

	case OpRetire:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("retire: entry_id is required")
		}
		if op.Fields == nil {
			return errors.New("retire: fields is required")
		}
		reasonVal, ok := op.Fields["reason"]
		if !ok || reasonVal == nil {
			return errors.New("retire: fields must include reason")
		}
		reasonStr, ok := reasonVal.(string)
		if !ok || strings.TrimSpace(reasonStr) == "" {
			return errors.New("retire: fields reason must be a non-empty string")
		}

	case OpMove:
		if strings.TrimSpace(op.EntryID) == "" {
			return errors.New("move: entry_id is required")
		}
		if op.Fields == nil {
			return errors.New("move: fields is required")
		}
		toDossierVal, ok := op.Fields["to_dossier"]
		if !ok || toDossierVal == nil {
			return errors.New("move: fields must include to_dossier")
		}
		toDossierStr, ok := toDossierVal.(string)
		if !ok || strings.TrimSpace(toDossierStr) == "" {
			return errors.New("move: fields to_dossier must be a non-empty string")
		}

	case OpSplit:
		if strings.TrimSpace(op.DossierScope) == "" {
			return errors.New("split: dossier_scope is required")
		}
		if op.Fields == nil {
			return errors.New("split: fields is required")
		}
		newDossiersVal, ok := op.Fields["new_dossiers"]
		if !ok || newDossiersVal == nil {
			return errors.New("split: fields must include new_dossiers")
		}
		if err := validateStringList(newDossiersVal); err != nil {
			return fmt.Errorf("split: invalid new_dossiers: %w", err)
		}
		entryMovesVal, ok := op.Fields["entry_moves"]
		if !ok || entryMovesVal == nil {
			return errors.New("split: fields must include entry_moves")
		}
		if err := validateStringMap(entryMovesVal); err != nil {
			return fmt.Errorf("split: invalid entry_moves: %w", err)
		}

	case "":
		return errors.New("op type is required")

	default:
		return fmt.Errorf("invalid op type: %q", op.Type)
	}

	return nil
}

func validateStringList(val any) error {
	switch items := val.(type) {
	case []string:
		if len(items) == 0 {
			return errors.New("list cannot be empty")
		}
		for i, s := range items {
			if strings.TrimSpace(s) == "" {
				return fmt.Errorf("item at index %d is empty", i)
			}
		}
		return nil
	case []any:
		if len(items) == 0 {
			return errors.New("list cannot be empty")
		}
		for i, item := range items {
			s, ok := item.(string)
			if !ok || strings.TrimSpace(s) == "" {
				return fmt.Errorf("item at index %d is not a non-empty string", i)
			}
		}
		return nil
	default:
		return errors.New("must be a list of strings")
	}
}

func validateStringMap(val any) error {
	switch m := val.(type) {
	case map[string]string:
		if len(m) == 0 {
			return errors.New("map cannot be empty")
		}
		for k, v := range m {
			if strings.TrimSpace(k) == "" || strings.TrimSpace(v) == "" {
				return errors.New("keys and values must be non-empty strings")
			}
		}
		return nil
	case map[string]any:
		if len(m) == 0 {
			return errors.New("map cannot be empty")
		}
		for k, v := range m {
			if strings.TrimSpace(k) == "" {
				return errors.New("keys must be non-empty strings")
			}
			s, ok := v.(string)
			if !ok || strings.TrimSpace(s) == "" {
				return fmt.Errorf("value for key %q must be a non-empty string", k)
			}
		}
		return nil
	default:
		return errors.New("must be a map of string to string")
	}
}

// ValidateBatch validates all ops in a batch and required batch metadata.
func ValidateBatch(batch OpBatch) error {
	if batch.Version <= 0 {
		return errors.New("version must be >= 1")
	}
	if strings.TrimSpace(batch.BatchID) == "" {
		return errors.New("batch_id is required")
	}
	if batch.CreatedAt.IsZero() {
		return errors.New("created_at is required")
	}
	if len(batch.Ops) == 0 {
		return errors.New("ops cannot be empty")
	}
	for i, op := range batch.Ops {
		if err := ValidateOp(op); err != nil {
			return fmt.Errorf("op[%d]: %w", i, err)
		}
	}
	return nil
}

package ops

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Writer writes OpBatch objects to append-only JSON files on disk.
type Writer struct {
	baseDir string
}

// NewWriter creates a new Writer for the given base directory (.memory/ops).
func NewWriter(baseDir string) *Writer {
	return &Writer{
		baseDir: baseDir,
	}
}

// Write writes the batch as indented JSON to .memory/ops/<yyyy-mm>/<batch-id>.json,
// creating the month directory if needed.
func (w *Writer) Write(batch OpBatch) error {
	if err := ValidateBatch(batch); err != nil {
		return fmt.Errorf("validating batch: %w", err)
	}

	month := batch.CreatedAt.UTC().Format("2006-01")
	monthDir := filepath.Join(w.baseDir, month)
	if err := os.MkdirAll(monthDir, 0755); err != nil {
		return fmt.Errorf("creating month directory %s: %w", monthDir, err)
	}

	batchID := strings.TrimSuffix(batch.BatchID, ".json")
	filename := batchID + ".json"
	targetPath := filepath.Join(monthDir, filename)

	data, err := json.MarshalIndent(batch, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling batch: %w", err)
	}
	data = append(data, '\n')

	if err := os.WriteFile(targetPath, data, 0644); err != nil {
		return fmt.Errorf("writing batch file %s: %w", targetPath, err)
	}

	return nil
}

package ops

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Reader reads and validates OpBatch files from disk.
type Reader struct {
	baseDir string
	gitDir  string
}

// NewReader creates a new Reader for the given base directory (.memory/ops).
func NewReader(baseDir string) *Reader {
	return &Reader{
		baseDir: baseDir,
	}
}

// WithGitDir sets the git repository directory for git operations like resolveCommitTime.
func (r *Reader) WithGitDir(gitDir string) *Reader {
	r.gitDir = gitDir
	return r
}

// ReadBatch reads and validates a single batch file from the given path.
// The path may be absolute, relative to current working directory, relative to baseDir,
// or a simple batch ID / filename residing in one of the month subdirectories.
func (r *Reader) ReadBatch(path string) (*OpBatch, error) {
	target := path
	if _, err := os.Stat(target); err != nil {
		if !filepath.IsAbs(path) {
			candidate := filepath.Join(r.baseDir, path)
			if _, err := os.Stat(candidate); err == nil {
				target = candidate
			} else if filepath.Dir(path) == "." {
				// Search month subdirectories
				found := ""
				searchName := path
				if !strings.HasSuffix(searchName, ".json") {
					searchName += ".json"
				}
				entries, _ := os.ReadDir(r.baseDir)
				for _, e := range entries {
					if e.IsDir() {
						c := filepath.Join(r.baseDir, e.Name(), searchName)
						if _, err := os.Stat(c); err == nil {
							found = c
							break
						}
					}
				}
				if found != "" {
					target = found
				}
			}
		}
	}

	data, err := os.ReadFile(target)
	if err != nil {
		return nil, fmt.Errorf("reading batch file %s: %w", target, err)
	}

	var batch OpBatch
	if err := json.Unmarshal(data, &batch); err != nil {
		return nil, fmt.Errorf("unmarshaling batch file %s: %w", target, err)
	}

	if err := ValidateBatch(batch); err != nil {
		return nil, fmt.Errorf("validating batch %s: %w", target, err)
	}

	return &batch, nil
}

package ops

import (
	"context"
	"errors"
	"fmt"
	"io"
	"iter"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// Iterator provides cursor-style and pull-style iteration over op batches.
type Iterator struct {
	r    *Reader
	ctx  context.Context
	seq  iter.Seq2[*OpBatch, error]
	next func() (*OpBatch, error, bool)
	stop func()
}

// NewIterator creates a pull-style Iterator wrapping r.Iterate(ctx).
func NewIterator(r *Reader, ctx context.Context) *Iterator {
	if ctx == nil {
		ctx = context.Background()
	}
	seq := r.Iterate(ctx)
	next, stop := iter.Pull2(seq)
	return &Iterator{
		r:    r,
		ctx:  ctx,
		seq:  seq,
		next: next,
		stop: stop,
	}
}

// Next advances to the next batch in chronological order.
// Returns io.EOF when all batches have been read.
func (it *Iterator) Next() (*OpBatch, error) {
	if it.next == nil {
		return nil, io.EOF
	}
	batch, err, ok := it.next()
	if !ok {
		return nil, io.EOF
	}
	return batch, err
}

// Close stops the pull iterator and releases its resources.
func (it *Iterator) Close() {
	if it.stop != nil {
		it.stop()
		it.stop = nil
		it.next = nil
	}
}

// Seq returns the push-style iterator sequence for range loops.
func (it *Iterator) Seq() iter.Seq2[*OpBatch, error] {
	return it.seq
}

// Iterate yields all batches in chronological order (month directory order, then ULID order within month).
func (r *Reader) Iterate(ctx context.Context) iter.Seq2[*OpBatch, error] {
	return r.IterateAfter(ctx, "")
}

// IterateAfter yields only batches after afterBatchID in ULID order.
func (r *Reader) IterateAfter(ctx context.Context, afterBatchID string) iter.Seq2[*OpBatch, error] {
	return func(yield func(*OpBatch, error) bool) {
		if ctx == nil {
			ctx = context.Background()
		}
		if err := ctx.Err(); err != nil {
			yield(nil, err)
			return
		}

		afterID := strings.ToUpper(strings.TrimSuffix(strings.TrimSpace(afterBatchID), ".json"))

		monthEntries, err := os.ReadDir(r.baseDir)
		if err != nil {
			if os.IsNotExist(err) {
				return
			}
			yield(nil, fmt.Errorf("reading base directory %s: %w", r.baseDir, err))
			return
		}

		var monthDirs []string
		for _, me := range monthEntries {
			if me.IsDir() {
				monthDirs = append(monthDirs, me.Name())
			}
		}
		sort.Strings(monthDirs)

		for _, monthDir := range monthDirs {
			if err := ctx.Err(); err != nil {
				yield(nil, err)
				return
			}

			monthPath := filepath.Join(r.baseDir, monthDir)
			fileEntries, err := os.ReadDir(monthPath)
			if err != nil {
				if !yield(nil, fmt.Errorf("reading month directory %s: %w", monthPath, err)) {
					return
				}
				continue
			}

			var jsonFiles []string
			for _, fe := range fileEntries {
				if !fe.IsDir() && strings.HasSuffix(fe.Name(), ".json") {
					jsonFiles = append(jsonFiles, fe.Name())
				}
			}
			sort.Strings(jsonFiles)

			for _, fileName := range jsonFiles {
				if err := ctx.Err(); err != nil {
					yield(nil, err)
					return
				}

				filePath := filepath.Join(monthPath, fileName)
				batch, err := r.ReadBatch(filePath)
				if err != nil {
					if !yield(nil, err) {
						return
					}
					continue
				}

				if afterID != "" && strings.ToUpper(batch.BatchID) <= afterID {
					continue
				}

				if !yield(batch, nil) {
					return
				}
			}
		}
	}
}

func (r *Reader) resolveCommitTime(ctx context.Context, commit string) (time.Time, error) {
	commit = strings.TrimSpace(commit)
	if commit == "" {
		return time.Time{}, errors.New("commit hash cannot be empty")
	}

	cmd := exec.CommandContext(ctx, "git", "log", "-1", "--format=%cI", commit)
	if r.gitDir != "" {
		cmd.Dir = r.gitDir
	}
	out, err := cmd.Output()
	if err != nil {
		return time.Time{}, fmt.Errorf("git log failed for commit %s: %w", commit, err)
	}

	outStr := strings.TrimSpace(string(out))
	if outStr == "" {
		return time.Time{}, fmt.Errorf("no commit timestamp found for %s", commit)
	}

	t, err := time.Parse(time.RFC3339, outStr)
	if err != nil {
		return time.Time{}, fmt.Errorf("failed to parse commit timestamp %q: %w", outStr, err)
	}
	return t, nil
}

// IterateBefore yields only batches whose CreatedAt is before the given commit timestamp.
func (r *Reader) IterateBefore(ctx context.Context, beforeCommit string) iter.Seq2[*OpBatch, error] {
	return func(yield func(*OpBatch, error) bool) {
		cutoff, err := r.resolveCommitTime(ctx, beforeCommit)
		if err != nil {
			yield(nil, err)
			return
		}
		for batch, err := range r.IterateBeforeTime(ctx, cutoff) {
			if !yield(batch, err) {
				return
			}
		}
	}
}

// IterateBeforeTime yields only batches whose CreatedAt is before cutoff.
func (r *Reader) IterateBeforeTime(ctx context.Context, cutoff time.Time) iter.Seq2[*OpBatch, error] {
	return func(yield func(*OpBatch, error) bool) {
		for batch, err := range r.Iterate(ctx) {
			if err != nil {
				if !yield(nil, err) {
					return
				}
				continue
			}
			if batch.CreatedAt.Before(cutoff) {
				if !yield(batch, nil) {
					return
				}
			}
		}
	}
}

package ops

import (
	"fmt"
	"os"
	"path/filepath"
)

// MigrateV1Events archives existing v1 events data by moving eventsDir to archiveDir.
// If eventsDir does not exist, MigrateV1Events returns nil without doing anything.
func MigrateV1Events(eventsDir, archiveDir string) error {
	if _, err := os.Stat(eventsDir); os.IsNotExist(err) {
		return nil
	} else if err != nil {
		return fmt.Errorf("checking v1 events directory: %w", err)
	}

	if err := os.MkdirAll(filepath.Dir(archiveDir), 0755); err != nil {
		return fmt.Errorf("creating archive parent directory: %w", err)
	}

	if err := os.Rename(eventsDir, archiveDir); err != nil {
		return fmt.Errorf("migrating v1 events from %s to %s: %w", eventsDir, archiveDir, err)
	}

	return nil
}

