	}
}

func TestRoundTrip(t *testing.T) {
	tempDir := t.TempDir()
	w := ops.NewWriter(tempDir)
	r := ops.NewReader(tempDir)

	opTime := time.Date(2026, 10, 11, 8, 30, 0, 0, time.UTC)
	batchTime := time.Date(2026, 10, 11, 8, 35, 0, 0, time.UTC)

	batch := ops.NewBatchWithTime([]ops.Op{
		{
			Type:         ops.OpAdd,
			EntryID:      ops.NewEntryIDWithTime("inv", opTime),
			DossierScope: "core/test",
			Timestamp:    opTime,
			Source:       ops.SourceTurnNote,
			SessionID:    "sess-1234",
			Fields: map[string]any{
				"text":     "Rule text line 1\nline 2",
				"anchors":  []any{"path/file.go"},
				"verified": "2026-10-11",
			},
		},
		{
			Type:      ops.OpAmend,
			EntryID:   "inv-existing",
			Timestamp: opTime,
			Source:    ops.SourceHuman,
			Fields: map[string]any{
				"text": "amended invariant",
			},
		},
		{
			Type:      ops.OpSupersede,
			EntryID:   "inv-old",
			Timestamp: opTime,
			Source:    ops.SourceConsolidation,
			Fields: map[string]any{
				"new_entry_id": "inv-new",
				"text":         "replacement invariant",
			},
		},
		{
			Type:      ops.OpRetire,
			EntryID:   "inv-to-retire",
			Timestamp: opTime,
			Source:    ops.SourcePA,
			Fields: map[string]any{
				"reason": "refactored out",
			},
		},
		{
			Type:      ops.OpMove,
			EntryID:   "inv-to-move",
			Timestamp: opTime,
			Source:    ops.SourceSidecar,
			Fields: map[string]any{
				"to_dossier": "core/target",
			},
		},
		{
			Type:         ops.OpSplit,
			DossierScope: "core/monolith",
			Timestamp:    opTime,
			Source:       ops.SourceConsolidation,
			Fields: map[string]any{
				"new_dossiers": []any{"core/sub-a", "core/sub-b"},
				"entry_moves": map[string]any{
					"inv-1": "core/sub-a",
					"inv-2": "core/sub-b",
				},
			},
		},
	}, batchTime)

	if err := w.Write(batch); err != nil {
		t.Fatalf("w.Write() error = %v", err)
	}

	// Read by relative path: 2026-10/<batch_id>.json
	relPath := filepath.Join("2026-10", batch.BatchID+".json")
	read1, err := r.ReadBatch(relPath)
	if err != nil {
		t.Fatalf("r.ReadBatch(relPath) error = %v", err)
	}

	// Read by batchID directly
	read2, err := r.ReadBatch(batch.BatchID)
	if err != nil {
		t.Fatalf("r.ReadBatch(batchID) error = %v", err)
	}

	for _, read := range []*ops.OpBatch{read1, read2} {
		if read.Version != batch.Version {
			t.Errorf("version mismatch: got %d, want %d", read.Version, batch.Version)
		}
		if read.BatchID != batch.BatchID {
			t.Errorf("batch_id mismatch: got %s, want %s", read.BatchID, batch.BatchID)
		}
		if !read.CreatedAt.Equal(batch.CreatedAt) {
			t.Errorf("created_at mismatch: got %v, want %v", read.CreatedAt, batch.CreatedAt)
		}
		if len(read.Ops) != len(batch.Ops) {
			t.Fatalf("ops count mismatch: got %d, want %d", len(read.Ops), len(batch.Ops))
		}
		for i := range batch.Ops {
			expected := batch.Ops[i]
			actual := read.Ops[i]
			if actual.Type != expected.Type {
				t.Errorf("op[%d].Type = %s, want %s", i, actual.Type, expected.Type)
			}
			if actual.EntryID != expected.EntryID {
				t.Errorf("op[%d].EntryID = %s, want %s", i, actual.EntryID, expected.EntryID)
			}
			if actual.DossierScope != expected.DossierScope {
				t.Errorf("op[%d].DossierScope = %s, want %s", i, actual.DossierScope, expected.DossierScope)
			}
			if actual.Source != expected.Source {
				t.Errorf("op[%d].Source = %s, want %s", i, actual.Source, expected.Source)
			}
			if actual.SessionID != expected.SessionID {
				t.Errorf("op[%d].SessionID = %s, want %s", i, actual.SessionID, expected.SessionID)
			}
			if !actual.Timestamp.Equal(expected.Timestamp) {
				t.Errorf("op[%d].Timestamp = %v, want %v", i, actual.Timestamp, expected.Timestamp)
			}
			if len(actual.Fields) != len(expected.Fields) {
				t.Errorf("op[%d].Fields len = %d, want %d", i, len(actual.Fields), len(expected.Fields))
			}
		}
	}
}

func TestReader_Iterate(t *testing.T) {
	tempDir := t.TempDir()
	w := ops.NewWriter(tempDir)
	r := ops.NewReader(tempDir)

	t1 := time.Date(2026, 8, 1, 10, 0, 0, 0, time.UTC)
	t2 := time.Date(2026, 8, 15, 10, 0, 0, 0, time.UTC)
	t3 := time.Date(2026, 9, 1, 10, 0, 0, 0, time.UTC)

	b1 := ops.NewBatchWithTime([]ops.Op{
		{
			Type:         ops.OpAdd,
			EntryID:      "inv-01",
			DossierScope: "core/test",
			Fields:       map[string]any{"text": "inv 1"},
		},
	}, t1)

	b2 := ops.NewBatchWithTime([]ops.Op{
		{
			Type:         ops.OpAdd,
			EntryID:      "inv-02",
			DossierScope: "core/test",
			Fields:       map[string]any{"text": "inv 2"},
		},
	}, t2)

	b3 := ops.NewBatchWithTime([]ops.Op{
		{
			Type:         ops.OpAdd,
			EntryID:      "inv-03",
			DossierScope: "core/test",
			Fields:       map[string]any{"text": "inv 3"},
		},
	}, t3)

	// Write batches in arbitrary order
	if err := w.Write(b2); err != nil {
		t.Fatalf("w.Write(b2) error = %v", err)
	}
	if err := w.Write(b3); err != nil {
		t.Fatalf("w.Write(b3) error = %v", err)
	}
	if err := w.Write(b1); err != nil {
		t.Fatalf("w.Write(b1) error = %v", err)
	}

	var observedIDs []string
	ctx := context.Background()
	for batch, err := range r.Iterate(ctx) {
		if err != nil {
			t.Fatalf("unexpected iteration error: %v", err)
		}
		observedIDs = append(observedIDs, batch.BatchID)
	}

	expectedIDs := []string{b1.BatchID, b2.BatchID, b3.BatchID}
	if len(observedIDs) != len(expectedIDs) {
		t.Fatalf("got %d batches, want %d", len(observedIDs), len(expectedIDs))
	}
	for i := range expectedIDs {
		if observedIDs[i] != expectedIDs[i] {
			t.Errorf("batch[%d] = %s, want %s", i, observedIDs[i], expectedIDs[i])
		}
	}
}

func TestReader_IterateAfter(t *testing.T) {
	tempDir := t.TempDir()
	w := ops.NewWriter(tempDir)
	r := ops.NewReader(tempDir)

	t1 := time.Date(2026, 8, 1, 10, 0, 0, 0, time.UTC)
	t2 := time.Date(2026, 8, 15, 10, 0, 0, 0, time.UTC)
	t3 := time.Date(2026, 9, 1, 10, 0, 0, 0, time.UTC)

	b1 := ops.NewBatchWithTime([]ops.Op{
		{Type: ops.OpAdd, EntryID: "inv-01", DossierScope: "core/test", Fields: map[string]any{"text": "1"}},
	}, t1)
	b2 := ops.NewBatchWithTime([]ops.Op{
		{Type: ops.OpAdd, EntryID: "inv-02", DossierScope: "core/test", Fields: map[string]any{"text": "2"}},
	}, t2)
	b3 := ops.NewBatchWithTime([]ops.Op{
		{Type: ops.OpAdd, EntryID: "inv-03", DossierScope: "core/test", Fields: map[string]any{"text": "3"}},
	}, t3)

	for _, b := range []ops.OpBatch{b1, b2, b3} {
		if err := w.Write(b); err != nil {
			t.Fatalf("w.Write error = %v", err)
		}
	}

	ctx := context.Background()

	// Iterate after 1st batch: should return only 2nd and 3rd
	var after1IDs []string
	for batch, err := range r.IterateAfter(ctx, b1.BatchID) {
		if err != nil {
			t.Fatalf("IterateAfter(b1) error: %v", err)
		}
		after1IDs = append(after1IDs, batch.BatchID)
	}

	expectedAfter1 := []string{b2.BatchID, b3.BatchID}
	if len(after1IDs) != len(expectedAfter1) {
		t.Fatalf("IterateAfter(b1) returned %d items, want %d", len(after1IDs), len(expectedAfter1))
	}
	for i := range expectedAfter1 {
		if after1IDs[i] != expectedAfter1[i] {
			t.Errorf("IterateAfter(b1)[%d] = %s, want %s", i, after1IDs[i], expectedAfter1[i])
		}
	}

	// Iterate after 2nd batch: should return only 3rd
	var after2IDs []string
	for batch, err := range r.IterateAfter(ctx, b2.BatchID) {
		if err != nil {
			t.Fatalf("IterateAfter(b2) error: %v", err)
		}
		after2IDs = append(after2IDs, batch.BatchID)
	}
	if len(after2IDs) != 1 || after2IDs[0] != b3.BatchID {
		t.Fatalf("IterateAfter(b2) = %v, want [%s]", after2IDs, b3.BatchID)
	}

	// Iterate after 3rd batch: should return empty
	var after3IDs []string
	for batch, err := range r.IterateAfter(ctx, b3.BatchID) {
		if err != nil {
			t.Fatalf("IterateAfter(b3) error: %v", err)
		}
		after3IDs = append(after3IDs, batch.BatchID)
	}
	if len(after3IDs) != 0 {
		t.Fatalf("IterateAfter(b3) = %v, want empty", after3IDs)
	}
}

