func TestReader_IterateBefore_Git(t *testing.T) {
	// Initialize a temporary git repository
	gitDir := t.TempDir()
	runGit(t, gitDir, "init")
	runGit(t, gitDir, "config", "user.name", "Test User")
	runGit(t, gitDir, "config", "user.email", "test@example.com")

	// Commit 1
	file1 := filepath.Join(gitDir, "file1.txt")
	if err := os.WriteFile(file1, []byte("hello 1"), 0644); err != nil {
		t.Fatal(err)
	}
	runGit(t, gitDir, "add", "file1.txt")
	runGit(t, gitDir, "commit", "-m", "first commit")
	commit1Hash := getGitOutput(t, gitDir, "rev-parse", "HEAD")

	// Pause briefly to ensure different commit timestamps
	time.Sleep(1100 * time.Millisecond)

	// Commit 2
	file2 := filepath.Join(gitDir, "file2.txt")
	if err := os.WriteFile(file2, []byte("hello 2"), 0644); err != nil {
		t.Fatal(err)
	}
	runGit(t, gitDir, "add", "file2.txt")
	runGit(t, gitDir, "commit", "-m", "second commit")
	commit2Hash := getGitOutput(t, gitDir, "rev-parse", "HEAD")

	commit2TimeStr := getGitOutput(t, gitDir, "log", "-1", "--format=%cI", commit2Hash)
	commit2Time, err := time.Parse(time.RFC3339, commit2TimeStr)
	if err != nil {
		t.Fatalf("parsing commit2 time: %v", err)
	}

	// Create ops writer in a directory inside or outside gitDir
	opsDir := filepath.Join(gitDir, ".memory", "ops")
	w := ops.NewWriter(opsDir)
	r := ops.NewReader(opsDir).WithGitDir(gitDir)

	// Batch 1 created before commit 2
	b1 := ops.NewBatchWithTime([]ops.Op{
		{Type: ops.OpAdd, EntryID: "inv-01", DossierScope: "core/test", Fields: map[string]any{"text": "1"}},
	}, commit2Time.Add(-10*time.Minute))

	// Batch 2 created after commit 2
	b2 := ops.NewBatchWithTime([]ops.Op{
		{Type: ops.OpAdd, EntryID: "inv-02", DossierScope: "core/test", Fields: map[string]any{"text": "2"}},
	}, commit2Time.Add(10*time.Minute))

	if err := w.Write(b1); err != nil {
		t.Fatalf("w.Write(b1) error: %v", err)
	}
	if err := w.Write(b2); err != nil {
		t.Fatalf("w.Write(b2) error: %v", err)
	}

	ctx := context.Background()
	var observed []string
	for batch, err := range r.IterateBefore(ctx, commit2Hash) {
		if err != nil {
			t.Fatalf("IterateBefore error: %v", err)
		}
		observed = append(observed, batch.BatchID)
	}

	if len(observed) != 1 || observed[0] != b1.BatchID {
		t.Fatalf("IterateBefore(%s) = %v, want [%s]", commit2Hash, observed, b1.BatchID)
	}

	// IterateBefore invalid commit hash should yield error
	hadErr := false
	for _, err := range r.IterateBefore(ctx, "nonexistentcommit123456") {
		if err != nil {
			hadErr = true
			break
		}
	}
	if !hadErr {
		t.Errorf("expected error for nonexistent commit hash")
	}
	_ = commit1Hash
}

func TestIterator(t *testing.T) {
	tempDir := t.TempDir()
	w := ops.NewWriter(tempDir)
	r := ops.NewReader(tempDir)

	t1 := time.Date(2026, 8, 1, 10, 0, 0, 0, time.UTC)
	t2 := time.Date(2026, 8, 2, 10, 0, 0, 0, time.UTC)

	b1 := ops.NewBatchWithTime([]ops.Op{
		{Type: ops.OpAdd, EntryID: "inv-1", DossierScope: "core", Fields: map[string]any{"text": "1"}},
	}, t1)
	b2 := ops.NewBatchWithTime([]ops.Op{
		{Type: ops.OpAdd, EntryID: "inv-2", DossierScope: "core", Fields: map[string]any{"text": "2"}},
	}, t2)

	if err := w.Write(b1); err != nil {
		t.Fatal(err)
	}
	if err := w.Write(b2); err != nil {
		t.Fatal(err)
	}

	ctx := context.Background()
	it := ops.NewIterator(r, ctx)
	defer it.Close()

	// First Next()
	got1, err := it.Next()
	if err != nil {
		t.Fatalf("it.Next() 1 error = %v", err)
	}
	if got1.BatchID != b1.BatchID {
		t.Errorf("got %s, want %s", got1.BatchID, b1.BatchID)
	}

	// Second Next()
	got2, err := it.Next()
	if err != nil {
		t.Fatalf("it.Next() 2 error = %v", err)
	}
	if got2.BatchID != b2.BatchID {
		t.Errorf("got %s, want %s", got2.BatchID, b2.BatchID)
	}

	// Third Next() -> io.EOF
	got3, err := it.Next()
	if !errors.Is(err, io.EOF) {
		t.Fatalf("expected io.EOF on 3rd Next(), got %v (batch: %v)", err, got3)
	}

	// Seq() check
	it2 := ops.NewIterator(r, ctx)
	defer it2.Close()
	var seqIDs []string
	for b, err := range it2.Seq() {
		if err != nil {
			t.Fatal(err)
		}
		seqIDs = append(seqIDs, b.BatchID)
	}
	if len(seqIDs) != 2 || seqIDs[0] != b1.BatchID || seqIDs[1] != b2.BatchID {
		t.Errorf("it.Seq() = %v, want [%s, %s]", seqIDs, b1.BatchID, b2.BatchID)
	}
}

func TestMigrateV1Events(t *testing.T) {
	tempDir := t.TempDir()
	eventsDir := filepath.Join(tempDir, ".memory", "events")
	archiveDir := filepath.Join(tempDir, ".memory", "archive", "v1-events")

	// Case 1: eventsDir does not exist -> should return nil without error
	if err := ops.MigrateV1Events(eventsDir, archiveDir); err != nil {
		t.Fatalf("MigrateV1Events on non-existent dir returned error: %v", err)
	}

	// Case 2: eventsDir exists with mock data
	reviewsDir := filepath.Join(eventsDir, "reviews")
	if err := os.MkdirAll(reviewsDir, 0755); err != nil {
		t.Fatal(err)
	}
	sampleFile := filepath.Join(reviewsDir, "clm-01.jsonl")
	if err := os.WriteFile(sampleFile, []byte(`{"id":"clm-01","decision":"accept"}`), 0644); err != nil {
		t.Fatal(err)
	}

	// Run migration
	if err := ops.MigrateV1Events(eventsDir, archiveDir); err != nil {
		t.Fatalf("MigrateV1Events failed: %v", err)
	}

	// Verify old eventsDir does not exist
	if _, err := os.Stat(eventsDir); !os.IsNotExist(err) {
		t.Errorf("expected old eventsDir to be gone, but stat returned %v", err)
	}

	// Verify archived file exists
	archivedSample := filepath.Join(archiveDir, "reviews", "clm-01.jsonl")
	data, err := os.ReadFile(archivedSample)
	if err != nil {
		t.Fatalf("reading archived file %s failed: %v", archivedSample, err)
	}
	if !strings.Contains(string(data), "clm-01") {
		t.Errorf("archived file content mismatch: %s", string(data))
	}
}

func TestIDGenerators(t *testing.T) {
	now := time.Now().UTC()

	// NewBatchID
	bID1 := ops.NewBatchID()
	if len(bID1) != 26 {
		t.Errorf("expected 26 chars for BatchID, got %d (%s)", len(bID1), bID1)
	}

	// NewBatchIDWithTime
	bID2 := ops.NewBatchIDWithTime(now)
	if len(bID2) != 26 {
		t.Errorf("expected 26 chars for BatchIDWithTime, got %d (%s)", len(bID2), bID2)
	}

	// NewEntryID with prefix
	eID1 := ops.NewEntryID("inv")
	if !strings.HasPrefix(eID1, "inv-") {
		t.Errorf("expected inv- prefix, got %s", eID1)
	}

	// NewEntryID with trailing hyphen
	eID2 := ops.NewEntryID("rul-")
	if !strings.HasPrefix(eID2, "rul-") || strings.HasPrefix(eID2, "rul--") {
		t.Errorf("expected single rul- prefix, got %s", eID2)
	}

	// NewEntryID with empty prefix
	eID3 := ops.NewEntryID("")
	if len(eID3) != 26 {
		t.Errorf("expected 26 chars for empty prefix, got %d (%s)", len(eID3), eID3)
	}

	// NewEntryIDWithTime
	eID4 := ops.NewEntryIDWithTime("dec", now)
	if !strings.HasPrefix(eID4, "dec-") {
		t.Errorf("expected dec- prefix, got %s", eID4)
	}

	// NewBatch
	b := ops.NewBatch(nil)
	if b.Version != 1 {
		t.Errorf("expected Version 1, got %d", b.Version)
	}
	if b.CreatedAt.IsZero() {
		t.Errorf("expected non-zero CreatedAt")
	}
	if len(b.BatchID) != 26 {
		t.Errorf("expected 26 char BatchID, got %s", b.BatchID)
	}
}

func runGit(t *testing.T, dir string, args ...string) {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %v failed: %v\nOutput: %s", args, err, string(out))
	}
}

func getGitOutput(t *testing.T, dir string, args ...string) string {
	t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git %v failed: %v\nOutput: %s", args, err, string(out))
	}
	return strings.TrimSpace(string(out))
}

